import { useMemo } from "react";
export const useAxisLabels = (axis, options) => {
    const yLabels = useMemo(() => {
        // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
        if (axis && axis.yLabels && axis.yLabels.length > 0) {
            return axis.yLabels;
        }
        return [];
    }, [axis]);
    const xLabels = useMemo(() => {
        if (axis && axis.xLabel) {
            return axis.xLabel;
        }
        if (options.scales && options.scales.x && options.scales.x.title && options.scales.x.title.text) {
            if (typeof options.scales.x.title.text === "string") {
                return options.scales.x.title.text;
            }
            if (Array.isArray(options.scales.x.title.text)) {
                return options.scales.x.title.text[0];
            }
        }
        return undefined;
    }, [options, axis]);
    return { xLabels, yLabels };
};
